INSERT INTO public.metric_definition (metric_id, name, kpi_id, business_meaning, formula, numerator, denominator, aggregation, time_period, inclusion_exclusion, source_table_2025, source_table_future, value_nature, unit, sql, sql_hash, computable_2025, example_calculation, example_value_2025, valid_from, record_class, import_batch_id, source_ref, evidence_class, created_by) VALUES
('M-01', 'Cash collected before the fest', 'K-NS-01', 'The North Star: cash-type sponsorship actually received before festival start', 'SUM(receipt.amount) where receipt.received_at < fest_start and deal.support_type = cash', 'receipts before fest start', '—', 'sum', 'season to date; cut-off = festival start', 'Excludes in-kind, signed-but-unpaid and post-fest receipts', '—', 'receipts, invoices (Stage 8)', 'actual (live)', '₹', NULL, NULL, 'no', 'NOT COMPUTABLE on the 2025 dataset: no payment, invoice or receipt table exists (audit B12)', NULL, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-01', 'T', 'seed:04_reference_seed'),
('M-02', 'Signed (confirmed) value', 'K-G-01', 'Value agreed in confirmed partnerships; a leading indicator, not cash', 'SUM(confirmed_value_inr) of the latest version per opportunity with stage = partner_confirmed, as of D', 'confirmed value', '—', 'sum', 'as of a date (latest version ≤ end of day D)', 'Includes in-kind; excludes withdrawn/lost; never call it cash', 'core.opportunity_final / core.opportunity_asof(D)', 'deal versions', 'actual (synthetic 2025)', '₹', 'select sum(f.confirmed_value_inr) from core.opportunity_final f join stg.opportunities o using(opportunity_id) where f.stage=''partner_confirmed''', 'f50ab29981e8d7dea70f08e18de4289787aa8bae0c3195727078ab1e958f7d31', 'yes', '2025 (synthetic): 2240000', 2240000.0, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-02', 'T', 'seed:04_reference_seed'),
('M-03', 'Signed cash-type value', 'K-G-01', 'Signed value of deals whose consideration is cash', 'SUM(confirmed_value_inr) where support_type = cash', 'cash-type confirmed value', '—', 'sum', 'as of a date', 'Excludes in-kind deals', 'core.opportunity_final × stg.opportunities', 'deal versions', 'actual (synthetic 2025)', '₹', 'select sum(f.confirmed_value_inr) from core.opportunity_final f join stg.opportunities o using(opportunity_id) where f.stage=''partner_confirmed'' and o.support_type=''cash''', 'c9f63fccbddad2cd6201a6c9a529ede0f95360595445d30c04874ec77884932a', 'yes', '2025 (synthetic): 2000000', 2000000.0, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-03', 'T', 'seed:04_reference_seed'),
('M-04', 'In-kind value', NULL, 'Signed value of goods or services instead of cash; never counted as cash', 'SUM(confirmed_value_inr) where support_type = in_kind', 'in-kind confirmed value', '—', 'sum', 'as of a date', 'Reported in its own column', 'core.opportunity_final × stg.opportunities', 'deal versions', 'actual (synthetic 2025)', '₹', 'select sum(f.confirmed_value_inr) from core.opportunity_final f join stg.opportunities o using(opportunity_id) where f.stage=''partner_confirmed'' and o.support_type=''in_kind''', '9d99f2df78fd14e4a26c05f6abd010bafdf8cce632c05fcd86c3eca472352fdf', 'yes', '2025 (synthetic): 240000', 240000.0, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-04', 'T', 'seed:04_reference_seed'),
('M-05', 'Cash-type share of signed value', NULL, 'Share of signed value that is cash-type', 'M-03 ÷ M-02', 'signed cash-type value', 'signed value', 'ratio', 'as of a date', '—', 'as M-02, M-03', 'deal versions', 'calculated', 'ratio', 'select round(sum(case when o.support_type=''cash'' then f.confirmed_value_inr end)/sum(f.confirmed_value_inr),4) from core.opportunity_final f join stg.opportunities o using(opportunity_id) where f.stage=''partner_confirmed''', '70d45e32bfdc3838d2a3516e9f7f83d3e9eb092a04d59b2fda84b3d068bba212', 'yes', '2025 (synthetic): 0.8929', 0.8929, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-05', 'T', 'seed:04_reference_seed'),
('M-06', 'Collected ÷ signed cash', 'K-G-02', 'Whether signed value is becoming money before the fest (T−7 gate ≥ 0.85)', 'M-01 ÷ M-03', 'cash collected', 'signed cash-type value', 'ratio', 'weekly from W4; gate at T−7', 'Cash-type deals only', '—', 'receipts, deal versions', 'calculated (live)', 'ratio', NULL, NULL, 'no', 'NOT COMPUTABLE on the 2025 dataset: no payment, invoice or receipt table exists (audit B12)', NULL, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-06', 'T', 'seed:04_reference_seed'),
('M-07', 'Outstanding cash from signed sponsors', NULL, 'Signed cash-type value not yet received', 'M-03 − M-01 (by deal: confirmed cash value − receipts)', 'signed cash − collected', '—', 'sum', 'as of a date', 'Cash-type deals only; post-fest payers flagged', '—', 'receipts, invoices, payment schedules', 'calculated (live)', '₹', NULL, NULL, 'no', 'NOT COMPUTABLE on the 2025 dataset: no payment, invoice or receipt table exists (audit B12)', NULL, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-07', 'T', 'seed:04_reference_seed'),
('M-08', 'Cumulative signed value by week', 'K-G-01', 'Pacing: signed value reached by the end of each week, compared with the W4–W9 gates', 'SUM(confirmed value of opportunities first confirmed ≤ end of week)', 'confirmed value', '—', 'cumulative sum', 'weekly', 'In-window channels only for the gates; pre-season premium value tracked separately (K-G-04); confirmed-then-withdrawn deals excluded at their final state', 'core.opportunity_stage_reached + core.opportunity_final', 'deal versions', 'actual (synthetic 2025)', '₹', 'select sum(f.confirmed_value_inr) from core.opportunity_final f join core.opportunity_stage_reached r using(opportunity_id) where f.stage=''partner_confirmed'' and r.stage=''partner_confirmed'' and r.first_reached_at_ist < timestamp ''2025-03-16''', 'a3c95c57c712bda789e1c7258ca413165c55c1e01456c89698c5282451b0810c', 'yes', 'Confirmed before 16 Mar 2025 (end of 15 Mar): ₹14.25L signed', 1425000.0, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-08', 'T', 'seed:04_reference_seed'),
('M-09', 'Confirmed partnerships', NULL, 'Count of opportunities in partner_confirmed at the cut-off', 'COUNT(opportunity) with latest stage = partner_confirmed', 'confirmed opportunities', '—', 'count', 'as of a date', 'One brand can have several opportunities', 'core.opportunity_final', 'deal versions', 'actual (synthetic 2025)', 'opportunities', 'select count(*) from core.opportunity_final where stage=''partner_confirmed''', 'ac02d1da429ee21649cc315ba2aa60955f7bcaefab055992364dc682789d589d', 'yes', '2025 (synthetic): 24', 24.0, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-09', 'T', 'seed:04_reference_seed'),
('M-10', 'Qualified brands', NULL, 'Brands whose latest qualification version is qualified', 'COUNT(brand) with latest qualification_status = qualified as of D', 'qualified brands', '—', 'count', 'as of a date', 'Latest version only; never sum versions', 'core.qualification_final / core.qualification_asof(D)', 'qualification versions', 'actual (synthetic 2025)', 'brands', 'select count(*) from core.qualification_final where qualification_status=''qualified''', 'c6dcfc59245060945d9ad6b20c58c31584741b7539d52c657802c2780cc2bf7a', 'yes', '2025 (synthetic): 60', 60.0, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-10', 'T', 'seed:04_reference_seed'),
('M-11', 'Meeting rate', 'K-F-01', 'Share of touched brands that held a meeting', 'brands met ÷ brands touched, per campaign or channel group', 'brands with meeting_held', 'brands touched', 'ratio', 'season to date', 'Attempts before festival start; brand level', 'eda.q4_campaign_funnel', 'attempts, interactions', 'calculated', 'ratio', 'select round(sum(brands_met)::double/sum(brands_touched),3) from eda.q4_campaign_funnel where campaign_name=''Creator Network Referrals''', 'd394cc8958c3f93c8cf10d772807974c1315a9841cea65e6e8593bf0178eb8b4', 'yes', 'Creator referrals: 15 ÷ 19 = 0.789', 0.789, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-11', 'T', 'seed:04_reference_seed'),
('M-12', 'Proposal rate (brand level)', 'K-F-02', 'Share of met warm/inbound brands that received a proposal', 'brands with a proposal ÷ brands met', 'qualified brands with a proposal (val.handoff_register status C)', 'brands met', 'ratio', 'season to date', 'Brand level (a brand with two opportunities counts once)', 'val.handoff_register; eda.q4_campaign_funnel', 'opportunities, stage versions', 'calculated', 'ratio', 'select round(count(*) filter (where h.handoff_status=''C_proposal_sent'')::double/(select brands_met from eda.q4_campaign_funnel where campaign_name=''Creator Network Referrals''),3) from val.handoff_register h where h.qual_campaign=''Creator Network Referrals''', 'a2e3bb8beee2719ac0e30e27eb15b8925ccf2dd9dbcc687315f062ad11690758', 'yes', 'Creator referrals: 9 ÷ 15 = 0.600', 0.6, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-12', 'T', 'seed:04_reference_seed'),
('M-13', 'Win rate per proposal', 'K-F-03', 'Share of proposals that became confirmed partnerships', 'won opportunities ÷ opportunities that reached proposal_sent', 'won', 'proposals', 'ratio', 'season to date', 'Opportunity level; withdrawn after confirmation counts as not won', 'eda.q4_campaign_funnel', 'opportunities', 'calculated', 'ratio', 'select round(sum(won)::double/sum(proposals),3) from eda.q4_campaign_funnel where channel_group=''cold''', 'a74a298586ee5fd328889c8ba921bb25da9cc86451ba8d376aa4745bf34bab31', 'yes', 'Cold: 0 ÷ 21 = 0.000', 0.0, '2026-11-26 00:00:00+05:30', 'operating_plan', 'IB-REF-METRICS', '06_BUSINESS_KNOWLEDGE_BASE/metric_definitions/metric_dictionary.csv#M-13', 'T', 'seed:04_reference_seed'),
